-- validation: dozer roll date server-authoritative check
-- rejects dozer_rolls inserts where the roll_date does not match
-- the server's timezone-aligned operational date.
-- ==========================================================

create or replace function validate_dozer_roll_date()
returns trigger as $$
declare
  v_server_date date;
begin
  -- resolve today's date in africa/johannesburg timezone
  v_server_date := (current_timestamp at time zone 'africa/johannesburg')::date;

  if new.roll_date != v_server_date then
    raise exception 'invalid roll date (%): does not match server operational date (%)', new.roll_date, v_server_date;
  end if;

  return new;
end;
$$ language plpgsql security definer;

-- bind the validation trigger
drop trigger if exists trg_validate_dozer_roll_date on dozer_rolls;
create trigger trg_validate_dozer_roll_date
  before insert or update on dozer_rolls
  for each row
  execute function validate_dozer_roll_date();

comment on function validate_dozer_roll_date() is 'enforces server-authoritative operational date alignment for dozer roll records';

migration 057: security fixes for p0 vulnerabilities packages/supabase/migrations/057_security_p0_fixes.sql -- migration 057: security fixes for p0 vulnerabilities
--
-- 1. redefine handle_new_user() trigger to ignore user-supplied metadata role.
-- 2. enforce column-level constraints on public.employees so non-admins cannot self-elevate.
-- 3. harden the employees_update_self_or_admin rls update policy with a with check clause.

-- ============================================
-- 1. redefine handle_new_user() trigger function
-- ============================================
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.employees (auth_id, full_name, role)
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'full_name', new.email),
    'operator' -- hardcode default to prevent raw_user_meta_data.role elevation
  );
  return new;
end;
$$;

-- ============================================
-- 2. create trigger function to enforce employee update constraints
-- ============================================
create or replace function public.enforce_employee_update_constraints()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- if the updater is not a system administrator, prevent changing key identity and access columns
  if not public.is_admin() then
    new.role := old.role;
    new.department_id := old.department_id;
    new.accessible_departments := old.accessible_departments;
    new.auth_id := old.auth_id;
  end if;
  return new;
end;
$$;

drop trigger if exists enforce_employee_update_constraints_trigger on public.employees;
create trigger enforce_employee_update_constraints_trigger
  before update on public.employees
  for each row
  execute function public.enforce_employee_update_constraints();

-- ============================================
-- 3. harden employees update rls policy
-- ============================================
drop policy if exists "employees_update_self_or_admin" on public.employees;
create policy "employees_update_self_or_admin" on public.employees
  for update to authenticated
  using ( auth_id = auth.uid() or public.is_admin() )
  with check ( auth_id = auth.uid() or public.is_admin() );

